const fs = require('fs');
const zlib = require('zlib');
const { pipeline } = require('stream/promises');

async function gzipFile(src, dest) {
  // Each chunk flows src -> gzip -> dest with automatic backpressure.
  // pipeline destroys all streams and rejects on ANY error in the chain.
  await pipeline(
    fs.createReadStream(src),
    zlib.createGzip(),
    fs.createWriteStream(dest)
  );
  console.log('compressed without buffering the whole file');
}

