const { Transform } = require('stream');

class UppercaseLines extends Transform {
  constructor(opts) {
    super(opts);
    this.leftover = '';
  }

  _transform(chunk, _enc, callback) {
    const data = this.leftover + chunk.toString();
    const lines = data.split('\n');
    this.leftover = lines.pop(); // last item may be a partial line
    for (const line of lines) this.push(line.toUpperCase() + '\n');
    callback(); // signals readiness for the next chunk (backpressure)
  }

  _flush(callback) {
    if (this.leftover) this.push(this.leftover.toUpperCase());
    callback();
  }
}

process.stdin.pipe(new UppercaseLines()).pipe(process.stdout);

