const { spawn } = require('child_process');

function listDir(path) {
  // Args as an array => no shell, so `path` cannot inject commands.
  const child = spawn('ls', ['-la', path], { shell: false });

  child.stdout.on('data', (chunk) => process.stdout.write(chunk)); // streamed
  child.stderr.on('data', (chunk) => process.stderr.write(chunk));
  child.on('error', (err) => console.error('spawn failed:', err.message));
  child.on('close', (code) => console.log(`exited with ${code}`));
}

