// FIX A: WeakMap keyed by object -> entry GC'd when the key is unreachable.
const meta = new WeakMap();
function tag(user) {
  meta.set(user, { seenAt: Date.now() });
}

// FIX B: bounded cache with eviction.
const MAX = 1000;
const cache = new Map();
function remember(user) {
  if (cache.size >= MAX) cache.delete(cache.keys().next().value); // evict oldest
  cache.set(user.id, user);
}

